mapper.select:
        select to_pid from bus_rel where DELFLAG_ = '1' and from_type = 'PSN' and to_type = 'PSN' and rel_category = 'A'
        and rel_category_sub in ('1','2','3','4') and from_pid = #{pid}
        union
        select from_pid from bus_rel where DELFLAG_ = '1' and from_type = 'PSN' and to_type = 'PSN' and rel_category =
        'A' and rel_category_sub in ('1','2','3','4') and to_pid = #{pid}

        select to_pid as pid,to_type as type from bus_rel where DELFLAG_ = '1' and rel_category = 'C' and
        rel_category_sub in ('10','14') and from_pid = #{pid} and from_type = #{type}
        union
        select from_pid as pid,from_type as type from bus_rel where DELFLAG_ = '1' and rel_category = 'D' and
        rel_category_sub = '18' and to_pid = #{pid} and to_type = #{type}
